 if(type==1){Add(exercise,"ما معنى هذه الجملة؟",20,Ink,true);Add(exercise,p.En,24).Ltr();AudioButtons(exercise,p.En);var opts=l.Phrases.Where(x=>x!=p).OrderBy(_=>Random.Shared.Next()).Take(3).Append(p).OrderBy(_=>Random.Shared.Next()).ToList();foreach(var option in opts){Button? b=null;b=Btn(option.Ar,()=>{if(answered)return;var ok=option==p;b!.BorderBrush=Brush(ok?"#4DAD64":"#DE8070");Check(ok);});exercise.Children.Add(b);}}
