 void Check(bool ok){if(answered)return;if(ok){answered=true;firstCorrect++;feedback.Text="✓ ممتاز! استخدمت الجملة بشكل صحيح.";feedback.Foreground=Green;next.IsEnabled=true;if(tasks[step].Type>=3&&!sessionMistakes.Contains(currentKey))S.Mark(currentKey,true);Save();}else{wrong++;sessionMistakes.Add(currentKey);S.Mark(currentKey,false);Save();feedback.Text="حاول مرة أخرى. يمكنك الاستماع للجملة أو مراجعة التلميح.";feedback.Foreground=Brush("#B56148");}}
