 void AudioButtons(Panel panel,string text,bool recorder=false){var actions=new WrapPanel();actions.Children.Add(Btn("▶  استمع",()=>Speak(text,false)));actions.Children.Add(Btn("▷  ببطء",()=>Speak(text,true)));panel.Children.Add(actions);if(recorder){recordLabel=Text("",12,Muted);var row=new WrapPanel();row.Children.Add(Btn("●  سجّل / أوقف",()=>{if(recording){StopRecording();recordLabel.Text="تم إيقاف التسجيل. استمع وقارن.";}else BeginRecording();}));row.Children.Add(Btn("♫  اسمع تسجيلك",()=>{if(recording)StopRecording();if(recordingFile!=null&&File.Exists(recordingFile)){mciSendString("close playback",null,0,IntPtr.Zero);var code=mciSendString("open \""+recordingFile+"\" type waveaudio alias playback",null,0,IntPtr.Zero);if(code==0)mciSendString("play playback",null,0,IntPtr.Zero);else MessageBox.Show("تعذر تشغيل التسجيل.");}else MessageBox.Show("سجّل صوتك أولًا.");}));panel.Children.Add(row);panel.Children.Add(recordLabel);}}
 void BeginRecording(){StopSpeech();mciSendString("close recorder",null,0,IntPtr.Zero);if(mciSendString("open new type waveaudio alias recorder",null,0,IntPtr.Zero)!=0||mciSendString("record recorder",null,0,IntPtr.Zero)!=0){MessageBox.Show("تعذر الوصول للميكروفون. تحقق من توصيله ومن السماح لتطبيقات سطح المكتب باستخدامه في إعدادات Windows.");mciSendString("close recorder",null,0,IntPtr.Zero);return;}recording=true;recordLabel!.Text="● جارٍ التسجيل على جهازك فقط… اضغط الزر مجددًا للإيقاف.";}
 void StopRecording(){if(!recording)return;mciSendString("stop recorder",null,0,IntPtr.Zero);recordingFile=Path.Combine(Path.GetTempPath(),"TradeEnglish-practice.wav");var code=mciSendString("save recorder \""+recordingFile+"\"",null,0,IntPtr.Zero);mciSendString("close recorder",null,0,IntPtr.Zero);recording=false;if(code!=0){recordingFile=null;MessageBox.Show("تعذر حفظ التسجيل المؤقت.");}}
 void StopSpeech(){StopAudio();try{if(speech!=null&&!speech.HasExited)speech.Kill();}catch{}speech=null;mciSendString("close playback",null,0,IntPtr.Zero);}
 void Speak(string text,bool slow)=>SpeakNow(text,slow);
 void Review(){Clear();inLesson=false;Add(content,"المراجعة الذكية",30,Ink,true);var due=S.Review.Where(x=>x.Value.Due<=DateTime.Today).Select(x=>x.Key).ToList();Add(content,$"{due.Count} جملة تنتظر المراجعة",18,Green,true);Add(content,"الأخطاء تعود اليوم، ثم تتباعد المراجعات الناجحة: يوم، 3 أيام، أسبوع، أسبوعان، وشهر.",15,Muted);if(due.Count>0)content.Children.Add(Btn("ابدأ مراجعة قصيرة",()=>StartReview(due),true));else Add(content,"أكمل درسًا لتبدأ قائمة المراجعة. يمكنك أيضًا مراجعة جمل الدروس المكتملة الآن.",16);var learned=S.Review.Keys.ToList();if(learned.Count>0)content.Children.Add(Btn("تدريب إضافي على جمل سابقة",()=>StartReview(learned)));foreach(var key in due.Take(12)){var p=Course.Phrase(key);var box=new StackPanel();Add(box,p.En,19).Ltr();Add(box,p.Ar,15,Muted);content.Children.Add(Card(box));}}
 void StartReview(List<string> keys){reviewMode=true;tasks=keys.OrderBy(_=>Random.Shared.Next()).Take(12).Select((k,i)=>(k,i%2==0?3:4)).ToList();StartSession();}
 void Dictionary(){Clear();inLesson=false;Add(content,"جملك التجارية في مكان واحد",27,Ink,true);Add(content,"ابحث بالعربية أو الإنجليزية، واستمع لأي جملة.",14,Muted);var search=new TextBox{Padding=new(14),FontSize=18,Margin=new(0,15,0,10)};content.Children.Add(search);var favorites=new CheckBox{Content="المفضلة فقط",Margin=new(0,8,0,15)};content.Children.Add(favorites);var results=new StackPanel();content.Children.Add(results);void Render(){results.Children.Clear();var query=search.Text.Trim();int count=0;foreach(var l in Course.Lessons){for(int i=0;i<6;i++){var p=l.Phrases[i];var key=$"{l.Id}:{i}";if(favorites.IsChecked==true&&!S.Favorites.Contains(key))continue;if(!p.En.Contains(query,StringComparison.OrdinalIgnoreCase)&&!p.Ar.Contains(query))continue;count++;var item=new StackPanel();Add(item,l.Title,11,Muted);Add(item,p.En,20).Ltr();Add(item,p.Ar,16,Muted);var actions=new WrapPanel();actions.Children.Add(Btn("▶ استمع",()=>Speak(p.En,false)));actions.Children.Add(Btn(S.Favorites.Contains(key)?"★ إزالة":"☆ حفظ",()=>{if(!S.Favorites.Add(key))S.Favorites.Remove(key);Save();Render();}));item.Children.Add(actions);results.Children.Add(Card(item));}}if(count==0)Add(results,"لا توجد جمل تطابق البحث.",18,Muted);}search.TextChanged+=(_,_)=>Render();favorites.Checked+=(_,_)=>Render();favorites.Unchecked+=(_,_)=>Render();Render();}
 void Stats(){inLesson=false;Clear();Add(content,"كل خطوة تُحسب",30,Ink,true);Add(content,$"أكملت {S.Done.Count} من {Course.Lessons.Count} درسًا",22,Green,true);var b=new ProgressBar{Maximum=Course.Lessons.Count,Value=S.Done.Count,Height=18,Foreground=Green,Margin=new(0,15,0,15)};content.Children.Add(b);foreach(var u in Course.Units){var panel=new StackPanel();Add(panel,u.Title,19,Ink,true);Add(panel,$"{Course.Lessons.Count(l=>l.Unit==u.Id&&S.Done.Contains(l.Id))} / 6 دروس مكتملة",15,Muted);content.Children.Add(Card(panel));}Add(content,"آخر 7 أيام",20,Ink,true);for(int i=6;i>=0;i--){var d=DateTime.Today.AddDays(-i);Add(content,$"{d:MM/dd}     {S.Days.GetValueOrDefault(d.ToString("yyyy-MM-dd"))/60} دقيقة تدريب",15,Muted);}Add(content,"النقاط ومعدل الإكمال للتشجيع؛ ليست قياسًا رسميًا للطلاقة.",12,Muted);}
 void Help(){Clear();inLesson=false;Add(content,"تعلم قليلًا… واستخدمه كثيرًا",28,Ink,true);foreach(var s in new[]{"1. ابدأ من أول درس، ثم افتح الدروس بالتتابع. كل درس يحتوي على 24 خطوة، ويمكن إعادته متى شئت.","2. في بطاقات التعلم، استمع وكرر وسجّل صوتك. استمع لتسجيلك وقارنه بالصوت المرجعي؛ لا يوجد تقييم نطق آلي.","3. رتّب الكلمات بالنقر عليها. لإزالة كلمة من الإجابة، انقر عليها مرة أخرى.","4. في الكتابة نتدرّب على صياغة محددة، مع تجاهل حالة الأحرف والترقيم. عند الحاجة اضغط التلميح.","5. الأخطاء والتلميحات تُعيد الجمل إلى المراجعة. مراجعة اليوم أهم من جمع النقاط.","6. الهدف 30 دقيقة يوميًا، نصفها صوت وتحدث. العداد يحسب وقت وجود نافذة الدرس في المقدمة.","7. التقدم محفوظ محليًا بشكل مستقل عن النسخة السابقة. التسجيل مؤقت على جهازك ولا يُرسل لأي خدمة.","8. صوت Windows مجاني ومحلي. يمكنك اختيار ElevenLabs من إعدادات الصوت؛ توليد المقاطع يستهلك رصيد حسابك بعد تفعيله، ويعاد تشغيل الملفات المحفوظة دون توليد جديد.","9. المحتوى يغطي أساسيات ومواقف تجارية متقدمة؛ الإتقان يحتاج تطبيقًا ومحادثة حقيقية أيضًا. تمارين الشروط والمستندات للتعلم اللغوي."})content.Children.Add(Card(Text(s,16)));}
}
